inline bool VerifyLogLocalBody(::flatbuffers::Verifier &verifier, const void *obj, LogLocalBody type) {
  switch (type) {
    case LogLocalBody_NONE: {
      return true;
    }
    case LogLocalBody_LogConnectionState: {
      auto ptr = reinterpret_cast<const Tryll::LogConnectionState *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case LogLocalBody_LogLocalError: {
      auto ptr = reinterpret_cast<const Tryll::LogLocalError *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case LogLocalBody_LogCaptureGap: {
      auto ptr = reinterpret_cast<const Tryll::LogCaptureGap *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyLogLocalBodyVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyLogLocalBody(
        verifier,  values->Get(i), types->GetEnum<LogLocalBody>(i))) {
      return false;
    }
  }
  return true;
}

inline void *LogLocalBodyUnion::UnPack(const void *obj, LogLocalBody type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case LogLocalBody_LogConnectionState: {
      auto ptr = reinterpret_cast<const Tryll::LogConnectionState *>(obj);
      return ptr->UnPack(resolver);
    }
    case LogLocalBody_LogLocalError: {
      auto ptr = reinterpret_cast<const Tryll::LogLocalError *>(obj);
      return ptr->UnPack(resolver);
    }
    case LogLocalBody_LogCaptureGap: {
      auto ptr = reinterpret_cast<const Tryll::LogCaptureGap *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> LogLocalBodyUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case LogLocalBody_LogConnectionState: {
      auto ptr = reinterpret_cast<const Tryll::LogConnectionStateT *>(value);
      return CreateLogConnectionState(_fbb, ptr, _rehasher).Union();
    }
    case LogLocalBody_LogLocalError: {
      auto ptr = reinterpret_cast<const Tryll::LogLocalErrorT *>(value);
      return CreateLogLocalError(_fbb, ptr, _rehasher).Union();
    }
    case LogLocalBody_LogCaptureGap: {
      auto ptr = reinterpret_cast<const Tryll::LogCaptureGapT *>(value);
      return CreateLogCaptureGap(_fbb, ptr, _rehasher).Union();
    }
    default: return 0;
  }
}

inline LogLocalBodyUnion::LogLocalBodyUnion(const LogLocalBodyUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case LogLocalBody_LogConnectionState: {
      value = new Tryll::LogConnectionStateT(*reinterpret_cast<Tryll::LogConnectionStateT *>(u.value));
      break;
    }
    case LogLocalBody_LogLocalError: {
      value = new Tryll::LogLocalErrorT(*reinterpret_cast<Tryll::LogLocalErrorT *>(u.value));
      break;
    }
    case LogLocalBody_LogCaptureGap: {
      value = new Tryll::LogCaptureGapT(*reinterpret_cast<Tryll::LogCaptureGapT *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void LogLocalBodyUnion::Reset() {
  switch (type) {
    case LogLocalBody_LogConnectionState: {
      auto ptr = reinterpret_cast<Tryll::LogConnectionStateT *>(value);
      delete ptr;
      break;
    }
    case LogLocalBody_LogLocalError: {
      auto ptr = reinterpret_cast<Tryll::LogLocalErrorT *>(value);
      delete ptr;
      break;
    }
    case LogLocalBody_LogCaptureGap: {
      auto ptr = reinterpret_cast<Tryll::LogCaptureGapT *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = LogLocalBody_NONE;
}

